      "keystrokes": "cat > /app/src/BankBatchJob.java <<'EOF'
import java.io.*;
import java.math.*;
import java.nio.file.*;
import java.security.*;
import java.sql.*;
import java.text.*;
import java.util.*;

public class BankBatchJob {
    // Helper classes
    static class Account {
        String accountId;
        String currency;
        BigDecimal startBalance;
        BigDecimal baseApr;
        BigDecimal tierThreshold;
        BigDecimal tierApr;
        BigDecimal promoApr;
        int promoDays;
        Date openedAt;
        // other fields as needed
    }
    static class Transaction {
        int rowNum; // 1-based data row
        String txId;
        String accountId;
        String status;
        String type; // DEBIT or CREDIT
        BigDecimal amount;
        String currency;
        Date effectiveDate;
        String reversalOf; // may be null
        // other fields as needed
    }
    static class FxRate {
        String from;
        String to;
        Date rateDate;
        BigDecimal rate;
    }
    static class FxPivot {
        String from;
        String to;
        String via;
    }
    static class FeeRule {
        String accountId;
        String feePlan; // e.g., ALL, DEBIT, CREDIT
        BigDecimal flatFee;
        BigDecimal percentFee; // as decimal (e.g., 0.001 for 0.1%) 
        BigDecimal minFee;
        BigDecimal maxFee;
    }

    // Rounding helpers
    private static BigDecimal roundHalfEven(BigDecimal value, int scale) {
        return value.setScale(scale, RoundingMode.HALF_EVEN);
    }

    public static void main(String[] args) throws Exception {
        // Paths
        Path dataDir = Paths.get("/app/data");
        Path outputDir = Paths.get("/app/output");
        Files.createDirectories(outputDir);

        // Load business date
        String bizDateStr = new String(Files.readAllBytes(dataDir.resolve("biz_date.txt"))."trim"());
        SimpleDateFormat sdf = new SimpleDateFormat("yyyy-MM-dd");
        Date bizDate = sdf.parse(bizDateStr);

        // Load accounts
        Map<String, Account> accounts = new HashMap<String, Account>();
        try (BufferedReader br = Files.newBufferedReader(dataDir.resolve("accounts.csv"))) {
            String line;
            while ((line = br.readLine()) != null) {
                if (line.isEmpty()) continue;
                String[] parts = line.split(",");
                // Expected columns: account_id,currency,start_balance,base_apr,tier_threshold,tier_apr,promo_apr,promo_days,opened_at
                Account acc = new Account();
                acc.accountId = parts[0];
                acc.currency = parts[1];
                acc.startBalance = new BigDecimal(parts[2]);
                acc.baseApr = new BigDecimal(parts[3]);
                acc.tierThreshold = new BigDecimal(parts[4]);
                acc.tierApr = new BigDecimal(parts[5]);
                acc.promoApr = new BigDecimal(parts[6]);
                acc.promoDays = Integer.parseInt(parts[7]);
                acc.openedAt = sdf.parse(parts[8]);
                accounts.put(acc.accountId, acc);
            }
        }

        // Load fee rules
        Map<String, FeeRule> feeRules = new HashMap<String, FeeRule>();
        try (BufferedReader br = Files.newBufferedReader(dataDir.resolve("fee_rules.csv"))) {
            String line;
            while ((line = br.readLine()) != null) {
                if (line.isEmpty()) continue;
                String[] p = line.split(",");
                // account_id,fee_plan,flat_fee,percent_fee,min_fee,max_fee
                FeeRule fr = new FeeRule();
                fr.accountId = p[0];
                fr.feePlan = p[1];
                fr.flatFee = new BigDecimal(p[2]);
                fr.percentFee = new BigDecimal(p[3]);
                fr.minFee = new BigDecimal(p[4]);
                fr.maxFee = new BigDecimal(p[5]);
                feeRules.put(fr.accountId, fr);
            }
        }

        // Load FX rates
        List<FxRate> fxRates = new ArrayList<FxRate>();
        try (BufferedReader br = Files.newBufferedReader(dataDir.resolve("fx_rates.csv"))) {
            String line;
            while ((line = br.readLine()) != null) {
                if (line.isEmpty()) continue;
                String[] p = line.split(",");
                // from,to,rate_date,rate
                FxRate r = new FxRate();
                r.from = p[0];
                r.to = p[1];
                r.rateDate = sdf.parse(p[2]);
                r.rate = new BigDecimal(p[3]);
                fxRates.add(r);
            }
        }
        // Load FX pivots (order matters)
        List<FxPivot> fxPivots = new ArrayList<FxPivot>();
        try (BufferedReader br = Files.newBufferedReader(dataDir.resolve("fx_pivots.csv"))) {
            String line;
            while ((line = br.readLine()) != null) {
                if (line.isEmpty()) continue;
                String[] p = line.split(",");
                // from,to,via
                FxPivot fp = new FxPivot();
                fp.from = p[0];
                fp.to = p[1];
                fp.via = p[2];
                fxPivots.add(fp);
            }
        }

        // Load transactions
        List<Transaction> transactions = new ArrayList<Transaction>();
        try (BufferedReader br = Files.newBufferedReader(dataDir.resolve("transactions.csv"))) {
            String line;
            int rowNum = 0;
            while ((line = br.readLine()) != null) {
                rowNum++;
                if (line.isEmpty()) continue;
                String[] p = line.split(",");
                // Expected columns: tx_id,account_id,status,type,amount,currency,effective_date,reversal_of (may be empty)
                Transaction tx = new Transaction();
                tx.rowNum = rowNum;
                tx.txId = p[0];
                tx.accountId = p[1];
                tx.status = p[2];
                tx.type = p[3];
                tx.amount = new BigDecimal(p[4]);
                tx.currency = p[5];
                tx.effectiveDate = sdf.parse(p[6]);
                tx.reversalOf = (p.length > 7 && !p[7].isEmpty()) ? p[7] : null;
                transactions.add(tx);
            }
        }

        // Prepare H2 database
        String jdbcUrl = "jdbc:h2:/app/output/bankdb;MODE=DB2";
        Class.forName("org.h2.Driver"); // ensure driver loaded (H2 is on classpath in this image)
        try (Connection conn = DriverManager.getConnection(jdbcUrl, "sa", "")) {
            try (Statement st = conn.createStatement()) {
                st.execute("DROP TABLE IF EXISTS ACCOUNTS");
                st.execute("DROP TABLE IF EXISTS TXNS");
                st.execute("DROP TABLE IF EXISTS RUN_AUDIT");
                st.execute("CREATE TABLE ACCOUNTS (account_id VARCHAR PRIMARY KEY, currency VARCHAR, start_balance DECIMAL, base_apr DECIMAL, tier_threshold DECIMAL, tier_apr DECIMAL, promo_apr DECIMAL, promo_days INT, opened_at DATE)");
                st.execute("CREATE TABLE TXNS (row_num INT PRIMARY KEY, tx_id VARCHAR, account_id VARCHAR, status VARCHAR, type VARCHAR, amount DECIMAL, currency VARCHAR, effective_date DATE, reversal_of VARCHAR)");
                st.execute("CREATE TABLE RUN_AUDIT (jdbc_url VARCHAR, biz_date DATE, accounts INT, valid_txs INT, skipped_txs INT, report_md5 VARCHAR)");
                // Insert accounts
                String accInsert = "INSERT INTO ACCOUNTS (account_id,currency,start_balance,base_apr,tier_threshold,tier_apr,promo_apr,promo_days,opened_at) VALUES (?,?,?,?,?,?,?,?,?)";
                try (PreparedStatement ps = conn.prepareStatement(accInsert)) {
                    for (Account acc : accounts.values()) {
                        ps.setString(1, acc.accountId);
                        ps.setString(2, acc.currency);
                        ps.setBigDecimal(3, acc.startBalance);
                        ps.setBigDecimal(4, acc.baseApr);
                        ps.setBigDecimal(5, acc.tierThreshold);
                        ps.setBigDecimal(6, acc.tierApr);
                        ps.setBigDecimal(7, acc.promoApr);
                        ps.setInt(8, acc.promoDays);
                        ps.setDate(9, new java.sql.Date(acc.openedAt.getTime()));
                        ps.addBatch();
                    }
                    ps.executeBatch();
                }
                // Insert transactions (raw, before validation)
                String txInsert = "INSERT INTO TXNS (row_num,tx_id,account_id,status,type,amount,currency,effective_date,reversal_of) VALUES (?,?,?,?,?,?,?,?,?)";
                try (PreparedStatement ps = conn.prepareStatement(txInsert)) {
                    for (Transaction tx : transactions) {
                        ps.setInt(1, tx.rowNum);
                        ps.setString(2, tx.txId);
                        ps.setString(3, tx.accountId);
                        ps.setString(4, tx.status);
                        ps.setString(5, tx.type);
                        ps.setBigDecimal(6, tx.amount);
                        ps.setString(7, tx.currency);
                        ps.setDate(8, new java.sql.Date(tx.effectiveDate.getTime()));
                        ps.setString(9, tx.reversalOf);
                        ps.addBatch();
                    }
                    ps.executeBatch();
                }
            }
        }

        // Validation and processing
        Set<String> seenTxIds = new HashSet<String>();
        Map<String, Transaction> txIdMap = new HashMap<String, Transaction>(); // for reversal lookup
        for (Transaction tx : transactions) {
            txIdMap.put(tx.txId, tx);
        }
        List<String[]> exceptionRows = new ArrayList<String[]>();
        List<Transaction> validTxs = new ArrayList<Transaction>();
        for (Transaction tx : transactions) {
            // REVERSED: if any transaction has reversal_of pointing to this tx_id
            boolean isReversed = false;
            for (Transaction other : transactions) {
                if (other.reversalOf != null && other.reversalOf.equals(tx.txId)) {
                    isReversed = true;
                    break;
                }
            }
            if (isReversed) {
                exceptionRows.add(new String[]{String.valueOf(tx.rowNum), tx.txId, "REVERSED"});
                continue;
            }
            // REVERSAL_MISSING: if this transaction is a reversal but the original tx_id does not exist
            if (tx.reversalOf != null && !txIdMap.containsKey(tx.reversalOf)) {
                exceptionRows.add(new String[]{String.valueOf(tx.rowNum), tx.txId, "REVERSAL_MISSING"});
                continue;
            }
            // FX_MISSING: will be checked later when converting currency
            // AFTER_BIZ_DATE
            if (tx.effectiveDate.after(bizDate)) {
                exceptionRows.add(new String[]{String.valueOf(tx.rowNum), tx.txId, "AFTER_BIZ_DATE"});
                continue;
            }
            // status != POSTED
            if (!"POSTED".equalsIgnoreCase(tx.status)) {
                exceptionRows.add(new String[]{String.valueOf(tx.rowNum), tx.txId, "status"});
                continue;
            }
            // DUPLICATE
            if (seenTxIds.contains(tx.txId)) {
                exceptionRows.add(new String[]{String.valueOf(tx.rowNum), tx.txId, "DUPLICATE"});
                continue;
            }
            seenTxIds.add(tx.txId);
            validTxs.add(tx);
        }

        // Process valid transactions: currency conversion, fees, balance updates
        Map<String, BigDecimal> accountBalances = new HashMap<String, BigDecimal>();
        for (Account acc : accounts.values()) {
            accountBalances.put(acc.accountId, acc.startBalance);
        }
        BigDecimal totalInterestRaw = BigDecimal.ZERO;
        for (Transaction tx : validTxs) {
            Account acc = accounts.get(tx.accountId);
            if (acc == null) {
                // unknown account, treat as exception
                exceptionRows.add(new String[]{String.valueOf(tx.rowNum), tx.txId, "UNKNOWN_ACCOUNT"});
                continue;
            }
            // Determine FX rate to account currency if needed
            BigDecimal amountInAccCurr = null;
            if (!tx.currency.equals(acc.currency)) {
                // Find direct rate
                FxRate direct = null;
                for (FxRate r : fxRates) {
                    if (r.from.equals(tx.currency) && r.to.equals(acc.currency) && !r.rateDate.after(tx.effectiveDate)) {
                        if (direct == null || r.rateDate.after(direct.rateDate)) {
                            direct = r;
                        }
                    }
                }
                // Find reverse rate
                FxRate reverse = null;
                for (FxRate r : fxRates) {
                    if (r.from.equals(acc.currency) && r.to.equals(tx.currency) && !r.rateDate.after(tx.effectiveDate)) {
                        if (reverse == null || r.rateDate.after(reverse.rateDate)) {
                            reverse = r;
                        }
                    }
                }
                BigDecimal rateToUse = null;
                boolean useDirect = false;
                if (direct != null && reverse != null) {
                    int cmp = direct.rateDate.compareTo(reverse.rateDate);
                    if (cmp > 0) { useDirect = true; }
                    else if (cmp < 0) { useDirect = false; }
                    else { useDirect = true; }
                } else if (direct != null) {
                    useDirect = true;
                } else if (reverse != null) {
                    useDirect = false;
                }
                if (useDirect) {
                    rateToUse = direct.rate;
                } else if (reverse != null) {
                    // invert rate
                    rateToUse = BigDecimal.ONE.divide(reverse.rate, 20, RoundingMode.HALF_EVEN);
                }
                if (rateToUse != null) {
                    amountInAccCurr = roundHalfEven(tx.amount.multiply(rateToUse), 10);
                } else {
                    // Try pivots
                    boolean pivotFound = false;
                    for (FxPivot fp : fxPivots) {
                        if (fp.from.equals(tx.currency) && fp.to.equals(acc.currency)) {
                            // solve leg1 (from -> via)
                            BigDecimal leg1 = null;
                            // direct leg1
                            for (FxRate r : fxRates) {
                                if (r.from.equals(fp.from) && r.to.equals(fp.via) && !r.rateDate.after(tx.effectiveDate)) {
                                    if (leg1 == null || r.rateDate.after(((FxRate)leg1).rateDate)) {
                                        leg1 = r.rate;
                                    }
                                }
                            }
                            // reverse leg1
                            if (leg1 == null) {
                                for (FxRate r : fxRates) {
                                    if (r.from.equals(fp.via) && r.to.equals(fp.from) && !r.rateDate.after(tx.effectiveDate)) {
                                        leg1 = BigDecimal.ONE.divide(r.rate, 20, RoundingMode.HALF_EVEN);
                                        break;
                                    }
                                }
                            }
                            // solve leg2 (via -> to)
                            BigDecimal leg2 = null;
                            for (FxRate r : fxRates) {
                                if (r.from.equals(fp.via) && r.to.equals(fp.to) && !r.rateDate.after(tx.effectiveDate)) {
                                    if (leg2 == null || r.rateDate.after(((FxRate)leg2).rateDate)) {
                                        leg2 = r.rate;
                                    }
                                }
                            }
                            if (leg2 == null) {
                                for (FxRate r : fxRates) {
                                    if (r.from.equals(fp.to) && r.to.equals(fp.via) && !r.rateDate.after(tx.effectiveDate)) {
                                        leg2 = BigDecimal.ONE.divide(r.rate, 20, RoundingMode.HALF_EVEN);
                                        break;
                                    }
                                }
                            }
                            if (leg1 != null && leg2 != null) {
                                BigDecimal combined = leg1.multiply(leg2);
                                amountInAccCurr = roundHalfEven(tx.amount.multiply(combined), 10);
                                pivotFound = true;
                                break;
                            }
                        }
                    }
                    if (!pivotFound) {
                        exceptionRows.add(new String[]{String.valueOf(tx.rowNum), tx.txId, "FX_MISSING"});
                        continue;
                    }
                }
            } else {
                amountInAccCurr = roundHalfEven(tx.amount, 10);
            }
            // Apply fee
            FeeRule fr = feeRules.get(acc.accountId);
            if (fr == null) {
                // No fee rule, treat as zero fee
                fr = new FeeRule();
                fr.flatFee = BigDecimal.ZERO;
                fr.percentFee = BigDecimal.ZERO;
                fr.minFee = BigDecimal.ZERO;
                fr.maxFee = BigDecimal.ZERO;
                fr.feePlan = "ALL";
            }
            boolean applyFee = false;
            if ("ALL".equalsIgnoreCase(fr.feePlan)) applyFee = true;
            else if ("DEBIT".equalsIgnoreCase(fr.feePlan) && "DEBIT".equalsIgnoreCase(tx.type)) applyFee = true;
            else if ("CREDIT".equalsIgnoreCase(fr.feePlan) && "CREDIT".equalsIgnoreCase(tx.type)) applyFee = true;
            BigDecimal fee = BigDecimal.ZERO;
            if (applyFee) {
                BigDecimal pctPart = fr.percentFee.multiply(amountInAccCurr.abs());
                fee = fr.flatFee.add(pctPart);
                fee = roundHalfEven(fee, 2);
                if (fee.compareTo(fr.minFee) < 0) fee = fr.minFee;
                if (fee.compareTo(fr.maxFee) > 0) fee = fr.maxFee;
            }
            // Adjusted amount (sign stays as original)
            BigDecimal adjusted = amountInAccCurr.subtract(fee);
            adjusted = roundHalfEven(adjusted, 2);
            // Update balance
            BigDecimal prevBal = accountBalances.get(acc.accountId);
            BigDecimal newBal = prevBal.add(adjusted);
            accountBalances.put(acc.accountId, newBal);
        }

        // Compute interest and write interest.csv
        List<String[]> interestRows = new ArrayList<String[]>();
        for (Account acc : accounts.values()) {
            BigDecimal eodBal = accountBalances.get(acc.accountId);
            eodBal = roundHalfEven(eodBal, 2);
            // Determine APR
            BigDecimal apr = acc.baseApr;
            if (eodBal.compareTo(acc.tierThreshold) >= 0) {
                apr = apr.add(acc.tierApr);
            }
            // Promo APR
            long daysSinceOpened = (bizDate.getTime() - acc.openedAt.getTime()) / (1000L*60*60*24);
            if (acc.promoDays > 0 && daysSinceOpened < acc.promoDays) {
                apr = apr.add(acc.promoApr);
            }
            apr = roundHalfEven(apr, 6);
            // Daily interest raw
            BigDecimal dailyRaw = eodBal.multiply(apr).divide(new BigDecimal(365), 10, RoundingMode.HALF_EVEN);
            totalInterestRaw = totalInterestRaw.add(dailyRaw);
            BigDecimal dailyInterest = roundHalfEven(dailyRaw, 2);
            interestRows.add(new String[]{acc.accountId, bizDateStr, eodBal.toPlainString(), apr.toPlainString(), dailyInterest.toPlainString()});
        }
        // Sort by account_id
        Collections.sort(interestRows, new Comparator<String[]>() {
            public int compare(String[] a, String[] b) { return a[0].compareTo(b[0]); }
        });
        // Write interest.csv
        Path interestPath = outputDir.resolve("interest.csv");
        try (BufferedWriter bw = Files.newBufferedWriter(interestPath)) {
            for (String[] row : interestRows) {
                bw.write(String.join(",", row));
                bw.write('\n');
            }
        }
        // Write exceptions.csv
        Path excPath = outputDir.resolve("exceptions.csv");
        try (BufferedWriter bw = Files.newBufferedWriter(excPath)) {
            for (String[] row : exceptionRows) {
                bw.write(String.join(",", row));
                bw.write('\n');
            }
        }
        // Compute MD5 of interest.csv
        MessageDigest md5 = MessageDigest.getInstance("MD5");
        byte[] interestBytes = Files.readAllBytes(interestPath);
        byte[] digest = md5.digest(interestBytes);
        StringBuilder sb = new StringBuilder();
        for (byte b : digest) { sb.append(String.format("%02x", b)); }
        String md5Hex = sb.toString();
        // Write stats.json
        int totalValid = validTxs.size();
        int totalSkipped = exceptionRows.size();
        BigDecimal totalInterest = roundHalfEven(totalInterestRaw, 2);
        String json = String.format("{\"business_date\":\"%s\",\"accounts\":%d,\"valid_txs\":%d,\"skipped_txs\":%d,\"total_interest\":%s,\"report_md5\":\"%s\"}", bizDateStr, accounts.size(), totalValid, totalSkipped, totalInterest.toPlainString(), md5Hex);
        Files.write(outputDir.resolve("stats.json"), json.getBytes());
        // Insert audit row
        try (Connection conn = DriverManager.getConnection(jdbcUrl, "sa", "")) {
            try (PreparedStatement ps = conn.prepareStatement("INSERT INTO RUN_AUDIT (jdbc_url,biz_date,accounts,valid_txs,skipped_txs,report_md5) VALUES (?,?,?,?,?,?)")) {
                ps.setString(1, jdbcUrl);
                ps.setDate(2, new java.sql.Date(bizDate.getTime()));
                ps.setInt(3, accounts.size());
                ps.setInt(4, totalValid);
                ps.setInt(5, totalSkipped);
                ps.setString(6, md5Hex);
                ps.executeUpdate();
            }
        }
    }
}
